unitTests:
TEST("MAX in an expression") { CHECK_EQ(MAX(3, 7), 7); CHECK_EQ(MAX(7, 3), 7); CHECK_EQ(10 - MAX(2, 4), 6); CHECK_EQ(MAX(1 + 1, 3) * 2, 6); CHECK_EQ(MAX(-5, -9), -5); }
TEST("ABS of expressions") { CHECK_EQ(ABS(-4), 4); CHECK_EQ(ABS(4), 4); CHECK_EQ(ABS(2 - 5), 3); CHECK_EQ(ABS(3 - 10) * 2, 14); }
TEST("ARRAY_LEN") { int a[7]; double d[3]; char s[] = "hello"; CHECK_EQ(ARRAY_LEN(a), (size_t)7); CHECK_EQ(ARRAY_LEN(d), (size_t)3); CHECK_EQ(ARRAY_LEN(s), (size_t)6); CHECK_EQ(ARRAY_LEN(a) * 2, (size_t)14); (void)a; (void)d; }
TEST("IS_EVEN") { CHECK(IS_EVEN(4)); CHECK(!IS_EVEN(7)); CHECK(IS_EVEN(3 + 1)); CHECK(!IS_EVEN(2 + 1)); CHECK(IS_EVEN(0)); }
TEST("CLAMP") { CHECK_EQ(CLAMP(5, 0, 10), 5); CHECK_EQ(CLAMP(-3, 0, 10), 0); CHECK_EQ(CLAMP(12, 0, 10), 10); CHECK_EQ(CLAMP(2 + 9, 0, 5 + 5), 10); CHECK_EQ(CLAMP(5, 0, 10) * 3, 15); }
TEST("STRINGIFY") { CHECK_STR(STRINGIFY(a + b), "a + b"); CHECK_STR(STRINGIFY(hello), "hello"); }

